const effects=[];
function cellAt(px,py){const r=wrap.getBoundingClientRect();px=(px-r.width/2)/zoom+r.width/2;py=(py-r.height/2)/zoom+r.height/2;let x=(px-ox)/(cw),y=(py-oy)/(ch*.75);let yy=Math.round(y),xx=Math.round(x-(yy%2)*.5);let best=null,dist=Infinity;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){let a=xx+dx,b=yy+dy;if(!inside(a,b))continue;let p=point(a,b),d=(px-p[0])**2+(py-p[1])**2;if(d<dist){dist=d;best=[a,b]}}return dist<cw*cw?best:null}
function countTiles(p){let n=0;for(let i=0;i<owners.length;i++)if(owners[i]===p)n++;return n}
function showToast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),1500)}
function report(text){document.getElementById('report').textContent=text;document.getElementById('reportTime').textContent='JUST NOW'}
function capture(x,y,p,cost){let v=idx(x,y),old=owners[v];if(old===p)return false;if(terrain[v]===2)cost*=1.6;if(terrain[v]===3)cost*=2.5;if(buildings[v]===1)cost*=1.8;if(cost>factions[p].troops)return false;factions[p].troops-=cost;owners[v]=p;if(buildings[v]===1){cities[p]++;if(old<4)cities[old]=Math.max(0,cities[old]-1);report(`${factions[p].name} secured a city. Recruitment capacity increased.`)}if(old<4&&countTiles(old)===0){factions[old].alive=false;report(`${factions[old].name} has been eliminated from the sector.`);showToast(`${factions[old].name} eliminated`)}attacks++;return true}
function handleCell(x,y){let v=idx(x,y),owner=owners[v];if(action==='claim'){
if(owner===PLAYER)return;
let adjacent=neighbors(x,y).some(([a,b])=>owners[idx(a,b)]===PLAYER);if(!adjacent){showToast('Claim adjacent territory to expand');return}
let cost=(owner===NEUTRAL?24:Math.max(45,Math.round((factions[owner].troops/Math.max(1,countTiles(owner)))*1.25+32)))+(terrain[v]===2?24:terrain[v]===3?35:terrain[v]===1?8:0)+(buildings[v]===1?55:0);
if(terrain[v]===3&&!neighbors(x,y).some(([a,b])=>owners[idx(a,b)]===PLAYER&&terrain[idx(a,b)]!==3)){showToast('Land a transport from friendly coast');return}
if(capture(x,y,PLAYER,cost)){if(terrain[v]===3)report('Naval transports crossing open water are vulnerable. Establish a coastal route.');update()}else showToast('Insufficient reserve forces');return}
if(action==='city'||action==='tower'||action==='silo'){
if(owner!==PLAYER){showToast('Structures can only be placed in friendly territory');return}if(buildings[v]){if(action==='silo'&&buildings[v]===3){launch(x,y);return}showToast('This tile is already occupied');return}
let kind=action==='city'?1:action==='tower'?2:3,cost=kind===1?250:kind===2?180:600;if(factions[PLAYER].troops<cost){showToast(`Need ${cost} reserve forces`);return}factions[PLAYER].troops-=cost;buildings[v]=kind;if(kind===1)cities[PLAYER]++;if(kind===2)towers[PLAYER]++;if(kind===3)silos[PLAYER]++;report(kind===1?'City established. Recruitment rate increased.':kind===2?'Defense tower online. Nearby territory is reinforced.':'Missile silo online. Charge cycle initiated.');showToast(kind===3?'Silo online — charge cycle started':'Structure deployed');update()}}
function launch(x,y){if(silos[PLAYER]<1){showToast('Build a missile silo first');return}if(buildTimer>0){showToast(`Silo charging · ${Math.ceil(buildTimer)}s`);return}let target=cellAt(lastPointer.x,lastPointer.y);if(!target){showToast('Tap a target tile to launch');return}let [tx,ty]=target,tv=idx(tx,ty);if(owners[tv]===PLAYER){showToast('Choose an enemy or neutral target');return}if(factions[PLAYER].troops<220){showToast('Need 220 reserve forces to launch');return}factions[PLAYER].troops-=220;effects.push({x:tx,y:ty,t:performance.now()/1000});for(let yy=Math.max(0,ty-3);yy<=Math.min(H-1,ty+3);yy++)for(let xx=Math.max(0,tx-3);xx<=Math.min(W-1,tx+3);xx++){let distance=Math.hypot(xx-tx,yy-ty),iv=idx(xx,yy);if(distance<=3.3){irradiated[iv]=1;if(owners[iv]!==PLAYER){if(buildings[iv]===1&&owners[iv]<4)cities[owners[iv]]=Math.max(0,cities[owners[iv]]-1);buildings[iv]=0;owners[iv]=NEUTRAL}}}buildTimer=45;report('Nuclear strike deployed. Target zone irradiated; expect a 45-second recharge.');showToast('STRIKE DEPLOYED');update()}
let lastPointer={x:0,y:0};
function update(){let total=owners.length,ours=countTiles(PLAYER),pct=ours/total*100;document.getElementById('troops').innerHTML=`${Math.floor(factions[0].troops).toLocaleString()} <span>+</span>`;let cityRate=12+cities[0]*2.5;document.getElementById('rate').innerHTML=`+${cityRate.toFixed(0)}<span class="res-sub">/ sec</span>`;document.getElementById('controlPct').textContent=pct.toFixed(1)+'%';document.getElementById('controlBar').style.width=pct+'%';document.getElementById('tilesStat').textContent=`${ours.toLocaleString()} tiles`;document.getElementById('citiesStat').textContent=cities[0];document.getElementById('siloStat').textContent=silos[0]?`${Math.max(0,100-buildTimer/45*100).toFixed(0)}%`:'—';document.getElementById('scaleVal').textContent=Math.round(42/zoom);const names=document.getElementById('leaders');let html='';factions.slice(0,4).map((f,i)=>({f,i,n:countTiles(i)})).sort((a,b)=>b.n-a.n).forEach(({f,i,n},rank)=>{html+=`<div class="player"><span class="rank">0${rank+1}</span><span class="dot" style="--color:${colors()[i]}"></span><span class="player-name">${f.name}</span><span class="player-val">${(n/total*100).toFixed(1)}%</span></div>`});names.innerHTML=html;if(silos[0])document.querySelector('[data-build="silo"]').innerHTML=`<strong>◉</strong> Silo <em>${buildTimer>0?Math.ceil(buildTimer)+'s':'READY'}</em>`;if(pct>=99.8){finish(true)}else if(!factions[0].alive)finish(false)}
function finish(win){if(gameOver)return;gameOver=true;document.getElementById('endIcon').textContent=win?'✦':'✕';document.getElementById('endTitle').textContent=win?'Sector secured':'Nation eliminated';document.getElementById('endCopy').textContent=win?'The Arcadia sector is under your command. Your campaign is complete.':'Your forces have been routed. Regroup and try another strategy.';document.getElementById('overlay').classList.add('show')}
function tick(t){let dt=Math.min(.1,(t-last)/1000||0);last=t;if(!gameOver){elapsed+=dt;document.getElementById('clock').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;factions.forEach((f,i)=>{if(!f.alive)return;let territory=countTiles(i),rate=i===0?12+cities[i]*2.5:8+cities[i]*1.8;f.troops=Math.min(99999,f.troops+rate*dt+territory*.018*dt)});if(silos[0]&&buildTimer>0)buildTimer=Math.max(0,buildTimer-dt);if(Math.floor(elapsed*2)!==Math.floor((elapsed-dt)*2))update();if(Math.floor(elapsed)%1===0&&Math.random()<dt*.55)aiTurn();}requestAnimationFrame(tick)}
function aiTurn(){const diff=document.getElementById('difficulty').value,rate=diff==='easy'?.22:diff==='hard'?.78:.48;for(let p=1;p<4;p++){let f=factions[p];if(!f.alive||Math.random()>rate)continue;let candidates=[];for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++){let v=idx(x,y);if(owners[v]===p)continue;if(neighbors(x,y).some(([a,b])=>owners[idx(a,b)]===p))candidates.push([x,y])}if(!candidates.length)continue;candidates.sort((a,b)=>{let va=idx(...a),vb=idx(...b);return (buildings[vb]===1?2:0)+(owners[vb]!==NEUTRAL?1:0)-(buildings[va]===1?2:0)-(owners[va]!==NEUTRAL?1:0)});let target=candidates[Math.random()<.65?0:Math.random()*candidates.length|0],[x,y]=target;let cost=owners[idx(x,y)]===NEUTRAL?24:60;if(f.troops>cost)capture(x,y,p,cost)}update()}
function setAction(a){action=a;document.querySelectorAll('.action').forEach(b=>b.classList.toggle('selected',b.dataset.action===a));showToast(a==='claim'?'Claim mode active':`Select a friendly tile to build ${a}`)}

